using System.Data;using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Administration;using Microsoft.Data.SqlClient;namespace MediDesk.Data.Repositories;public sealed class SettingsRepository(SqlConnectionFactory f):ISettingsRepository{public async Task<IReadOnlyCollection<AppSettingDto>>GetAsync(CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var q=new SqlCommand("SELECT [Key],[Value],UpdatedAtUtc FROM AppSettings WHERE IsDeleted=0",c);await using var r=await q.ExecuteReaderAsync(ct);var a=new List<AppSettingDto>();while(await r.ReadAsync(ct))a.Add(new(r.GetString(0),r.GetString(1),DateTime.SpecifyKind(r.GetDateTime(2),DateTimeKind.Utc)));return a;}public async Task<IReadOnlyCollection<AppSettingDto>>UpdateAsync(Dictionary<string,string> values,long u,CancellationToken ct){await using var c=f.Create();await c.OpenAsync(ct);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(ct);foreach(var x in values){await using var q=new SqlCommand("MERGE AppSettings AS t USING (SELECT @K [Key],@V [Value]) s ON t.[Key]=s.[Key] WHEN MATCHED THEN UPDATE SET [Value]=s.[Value],UpdatedByUserId=@U,UpdatedAtUtc=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT([Key],[Value],UpdatedByUserId)VALUES(s.[Key],s.[Value],@U);",c,tx);q.Parameters.Add("@K",SqlDbType.NVarChar,80).Value=x.Key;q.Parameters.Add("@V",SqlDbType.NVarChar,500).Value=x.Value;q.Parameters.Add("@U",SqlDbType.BigInt).Value=u;await q.ExecuteNonQueryAsync(ct);}await tx.CommitAsync(ct);return await GetAsync(ct);}}

